import{_ as e,a0 as o,w as r,s as u,ao as l,I as t,x as n,a1 as p,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181211 Winterize your Bash prompt in Linux","title":"在 Linux 中打扮你的冬季 Bash 提示符","tag":"201901","desc":""},"relativePath":"201901/20181211 Winterize your Bash prompt in Linux.md","filePath":"[post].md"}'),d={name:"201901/20181211 Winterize your Bash prompt in Linux.md"};function g(k,s,m,b,f,h){const i=o("Link");return r(),u("div",null,[s[33]||(s[33]=l('<h1 id="在-linux-中打扮你的冬季-bash-提示符" tabindex="-1">在 Linux 中打扮你的冬季 Bash 提示符 <a class="header-anchor" href="#在-linux-中打扮你的冬季-bash-提示符" aria-label="Permalink to “在 Linux 中打扮你的冬季 Bash 提示符”">​</a></h1><blockquote><p>你的 Linux 终端可能支持 Unicode，那么为何不利用它在提示符中添加季节性的图标呢？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/uploads/linux-toy-bash-prompt.png?itok=HK_kVn37" alt=""></p><p>欢迎再次来到 Linux 命令行玩具日历的另一篇。如果这是你第一次访问该系列，你甚至可能会问自己什么是命令行玩具？我们对此比较随意：它会是终端上有任何有趣的消遣，对于任何节日主题相关的还有额外的加分。</p><p>也许你以前见过其中的一些，也许你没有。不管怎样，我们希望你玩得开心。</p><p>今天的玩具非常简单：它是你的 Bash 提示符。你的 Bash 提示符？是的！我们还有几个星期的假期可以盯着它看，在北半球冬天还会再多几周，所以为什么不玩玩它。</p><p>目前你的 Bash 提示符号可能是一个简单的美元符号（ <code>$</code>），或者更有可能是一个更长的东西。如果你不确定你的 Bash 提示符是什么，你可以在环境变量 <code>$PS1</code> 中找到它。要查看它，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $PS1</span></span></code></pre></div><p>对于我而言，它返回：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[\\u@\\h \\W]\\$</span></span></code></pre></div>',10)),t("p",null,[s[1]||(s[1]=t("code",null,"\\u",-1)),s[2]||(s[2]=n("、",-1)),s[3]||(s[3]=t("code",null,"\\h",-1)),s[4]||(s[4]=n(" 和 ",-1)),s[5]||(s[5]=t("code",null,"\\W",-1)),s[6]||(s[6]=n(" 分别是用户名、主机名和工作目录的特殊字符。你还可以使用其他一些符号。为了帮助构建你的 Bash 提示符，你可以使用 ",-1)),p(i,{href:"http://ezprompt.net/"},{default:a(()=>[...s[0]||(s[0]=[n("EzPrompt",-1)])]),_:1}),s[7]||(s[7]=n("，这是一个 ",-1)),s[8]||(s[8]=t("code",null,"PS1",-1)),s[9]||(s[9]=n(" 配置的在线生成器，它包含了许多选项，包括日期和时间、Git 状态等。",-1))]),t("p",null,[s[11]||(s[11]=n("你可能还有其他变量来组成 Bash 提示符。对我来说，",-1)),s[12]||(s[12]=t("code",null,"$PS2",-1)),s[13]||(s[13]=n(" 包含了我命令提示符的结束括号。有关详细信息，请参阅 ",-1)),p(i,{href:"https://access.redhat.com/solutions/505983"},{default:a(()=>[...s[10]||(s[10]=[n("这篇文章",-1)])]),_:1}),s[14]||(s[14]=n("。",-1))]),s[34]||(s[34]=l(`<p>要更改提示符，只需在终端中设置环境变量，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ PS1=&#39;\\u is cold: &#39;</span></span>
<span class="line"><span>jehb is cold:</span></span></code></pre></div><p>要永久设置它，请使用你喜欢的文本编辑器将相同的代码添加到 <code>/etc/bashrc</code> 中。</p><p>那么这些与冬季化有什么关系呢？好吧，你很有可能有现代一下的机器，你的终端支持 Unicode，所以你不仅限于标准的 ASCII 字符集。你可以使用任何符合 Unicode 规范的 emoji，包括雪花 ❄、雪人 ☃ 或一对滑雪板 🎿。你有很多冬季 emoji 可供选择。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>🎄 圣诞树</span></span>
<span class="line"><span>🧥 外套</span></span>
<span class="line"><span>🦌 鹿</span></span>
<span class="line"><span>🧤 手套</span></span>
<span class="line"><span>🤶 圣诞夫人</span></span>
<span class="line"><span>🎅 圣诞老人</span></span>
<span class="line"><span>🧣 围巾</span></span>
<span class="line"><span>🎿 滑雪者</span></span>
<span class="line"><span>🏂 滑雪板</span></span>
<span class="line"><span>❄ 雪花</span></span>
<span class="line"><span>☃ 雪人</span></span>
<span class="line"><span>⛄ 没有雪的雪人</span></span>
<span class="line"><span>🎁 包装好的礼物</span></span></code></pre></div><p>选择你最喜欢的，享受冬天的欢乐。有趣的事实：现代文件系统也支持文件名中的 Unicode 字符，这意味着技术上你可以将你下个程序命名为 <code>❄❄❄❄❄.py</code>。只是说说，不要这么做。</p><p>你有特别喜欢的命令行小玩具需要我介绍的吗？这个系列要介绍的小玩具大部分已经有了落实，但还预留了几个空位置。如果你有特别想了解的可以评论留言，我会查看的。如果还有空位置，我会考虑介绍它的。如果没有，但如果我得到了一些很好的意见，我会在最后做一些有价值的提及。</p>`,7)),t("p",null,[s[16]||(s[16]=n("查看昨天的玩具，",-1)),p(i,{href:"https://opensource.com/article/18/12/linux-toy-snake"},{default:a(()=>[...s[15]||(s[15]=[n("在 Linux 终端玩贪吃蛇",-1)])]),_:1}),s[17]||(s[17]=n("，记得明天再来！",-1))]),s[35]||(s[35]=t("hr",null,null,-1)),t("p",null,[s[19]||(s[19]=n("via: ",-1)),p(i,{href:"https://opensource.com/article/18/12/linux-toy-bash-prompt"},{default:a(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/18/12/linux-toy-bash-prompt",-1)])]),_:1})]),t("p",null,[s[24]||(s[24]=n("作者：",-1)),p(i,{href:"https://opensource.com/users/jason-baker"},{default:a(()=>[...s[20]||(s[20]=[n("Jason Baker",-1)])]),_:1}),s[25]||(s[25]=n(" 选题：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 译者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:a(()=>[...s[22]||(s[22]=[n("geekpi",-1)])]),_:1}),s[27]||(s[27]=n(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:a(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[30]||(s[30]=n("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原创编译，",-1)),p(i,{href:"https://linux.cn/"},{default:a(()=>[...s[29]||(s[29]=[n("Linux中国",-1)])]),_:1}),s[32]||(s[32]=n(" 荣誉推出",-1))])])}const y=e(d,[["render",g]]);export{C as __pageData,y as default};
